/**
 * 
 * @param {number[]} frequency  frequency in Hz
 * @param {number} temperature temperature in °C (20°C)
 * @param {number} humidity relative humidity in % (40%)
 * @param {number} pressure atmospheric pressure in Pa (101325 Pa)
 * @returns {number[]} db per m attenuation
 * @see http://en.wikibooks.org/wiki/Engineering_Acoustics/Outdoor_Sound_Propagation
 */
export function airAttenuation(
  frequency: number[],
  temperature: number = 20,
  humidity: number = 40,
  pressure: number = 101325
): number[] {
  const T = temperature + 273.15;
  const T0 = 293.15;
  const T01 = 273.16;

  const ps0 = 1.01325e5;
  const ps: number = pressure || ps0;

  const Csat = -6.8346 * Math.pow(T01 / T, 1.261) + 4.6151;
  const rhosat = Math.pow(10, Csat);
  const H = (rhosat * humidity * ps0) / ps;

  const frn = (ps / ps0) * Math.pow(T0 / T, 0.5) * (9 + 280 * H * Math.exp(-4.17 * (Math.pow(T0 / T, 1 / 3) - 1)));
  const fro = (ps / ps0) * (24.0 + (4.04e4 * H * (0.02 + H)) / (0.391 + H));

  const alphas: number[] = [];
  frequency.forEach(f => {
    const alpha = f ** 2 * (1.84e-11 / ((Math.pow(T0 / T, 0.5) * ps) / ps0) + Math.pow(T0 / T, -2.5) * ((0.1068 * Math.exp(-3352 / T) * frn) / (f * f + frn * frn) + (0.01278 * Math.exp(-2239.1 / T) * fro) / (f * f + fro * fro)));
    alphas.push((20 * alpha) / Math.log(10));
  });

  return alphas;
}

/**
 * `airAttenuation` is dB/m of SPL (20 log₁₀). Intensity / energy uses
 * 10 log₁₀, so the energy factor over distance r is 10^(-α_dB · r / 10).
 */
export function airAttenuationEnergy(airAbsDbPerMeter: number, distance: number): number {
  return 10 ** ((-airAbsDbPerMeter * distance) / 10);
}

/** Nepers/m for energy so that exp(-n · r) = airAttenuationEnergy(α_dB, r). */
export function airAbsDbToEnergyNepers(airAbsDbPerMeter: number): number {
  return airAbsDbPerMeter / (10 / Math.LN10);
}

/**
 * Nepers/m for **pressure amplitude**, so that `exp(-n · r)` is the amplitude
 * factor over distance `r` — half the energy figure above.
 *
 * Wave solvers carry pressure, not energy, so they need this one. Using the
 * energy nepers on a pressure field attenuates twice as fast in dB as the
 * standard says, which reads as a plausible but short reverberation time.
 */
export function airAbsDbToPressureNepers(airAbsDbPerMeter: number): number {
  return airAbsDbPerMeter / (20 / Math.LN10);
}
